import subprocess,pathlib
remote="python3 - <<'INNER'\nimport hashlib,json,pathlib,subprocess,tarfile,time\nr=pathlib.Path('/dataset/shaoshitong/search-r1-rl/topd');archive=r/'tools/qwen25-32b-startup-guard-v8-r2.tar.gz'\nassert hashlib.sha256(archive.read_bytes()).hexdigest()=='1c678db23b88459fa3bbb4cc9202bcd51d322573da7b1a6195e0c1f3b35ffb8c'\ntarget=r/'tools/qwen25-32b-startup-guard-candidate-v8';target.mkdir(exist_ok=True)\nwith tarfile.open(archive) as t:\n for m in t.getmembers():\n  assert m.isfile() and pathlib.PurePosixPath(m.name).parts[0]==target.name and len(pathlib.PurePosixPath(m.name).parts)==2 and pathlib.PurePosixPath(m.name).name not in ('.','..')\n  b=t.extractfile(m).read();p=target/pathlib.PurePosixPath(m.name).name\n  if p.exists():assert p.read_bytes()==b\n  else:p.write_bytes(b)\nfor n,h in json.loads((target/'files.json').read_text()).items():assert hashlib.sha256((target/n).read_bytes()).hexdigest()==h\nentry=r/'tools/startup-guard-v8-native-cpu.sbatch'\nassert hashlib.sha256(entry.read_bytes()).hexdigest()=='8e0718c8fcbe8ea4063fe73a5e4eba024f135894532edba720b7dc7885bfc55b'\nrecord=r/'logs/topd-startup-guard-cpu-v8-submission.json'\nif record.exists():\n d=json.loads(record.read_text());assert d['status']=='SUBMITTED',d\nelse:\n q=subprocess.check_output(['squeue','-h','-o','%i|%j'],text=True);assert not any(x.split('|',1)[-1]=='topd-startup-guard-cpu-v8' for x in q.splitlines())\n d=dict(status='UNKNOWN_BEFORE_SUBMISSION',scope='CPU_CONTRACT_NO_GPU_NO_QUALITY',entry=str(entry),epoch=time.time())\n record.write_text(json.dumps(d,indent=2)+'\\n')\n jid=subprocess.check_output(['sbatch','--parsable',str(entry)],text=True).strip().split(';')[0];assert jid.isdigit()\n d.update(status='SUBMITTED',job_id=int(jid));record.write_text(json.dumps(d,indent=2)+'\\n')\nprint(json.dumps(d))\nINNER"
p=subprocess.run(["python3","work/remote_topd.py"],input=remote,text=True,capture_output=True)
print(p.stdout,end="");print(p.stderr,end="")
if not p.returncode:pathlib.Path("outputs/topd-startup-guard-cpu-v8-submission.json").write_text(p.stdout)
